def load_table_catalog_metadata(
    mongo_uri: str = "",
    mongo_database: str = "",
    collection_name: str = "",
    limit: str = "1000",
    status_filter: str = "active",
) -> dict[str, Any]:
    config = _resolve_config(mongo_uri, mongo_database, collection_name)
    load_limit = _int(limit, 1000)
    if not config["mongo_uri"]:
        return _result("skipped", [], config, status_filter, [{"type": "missing_mongo_uri", "message": "MongoDB 연결 URI 노드 입력이 비어 있어 테이블 카탈로그 메타데이터를 불러오지 않았습니다."}])

    client = None
